mapper.sql:
WHERE c.OPERATOR_CODE = #{authorCode}

	AND p.PAYMENT_DATE >= #{startDate}


	AND p.PAYMENT_DATE <= #{endDate}


	AND p.STATUS = #{paymentStatus}


	AND (
		TO_CHAR(p.PAYMENT_CODE) LIKE '%' || #{keyword} || '%'
		OR c.NAME LIKE '%' || #{keyword} || '%'
		OR m.NAME LIKE '%' || #{keyword} || '%'
	)

mapper.select:

AND p.PAYMENT_CODE IN

	#{paymentCode}

ORDER BY p.PAYMENT_CODE

mapper.sql:
WHERE 1 = 1

	AND settlement_group.APPLIED_AT >= #{startDate}


	AND settlement_group.APPLIED_AT <= #{endDate}


	AND settlement_group.SETTLEMENT_STATUS = #{settlementStatus}


	AND (
		TO_CHAR(settlement_group.SETTLEMENT_CODE) LIKE '%' || #{keyword} || '%'
		OR EXISTS (
			SELECT 1 FROM CREATOR cr
			WHERE cr.OPERATOR_CODE = #{authorCode}
			  AND cr.SETTLEMENT_ACCOUNT LIKE '%' || #{keyword} || '%'
		)
	)

mapper.select:
SELECT *
FROM (
	SELECT settlement_page.*, ROWNUM AS RN
	FROM (
		SELECT settlement_group.*,
			(SELECT cr.SETTLEMENT_ACCOUNT FROM CREATOR cr
			 WHERE cr.OPERATOR_CODE = #{authorCode}) AS ACCOUNT_NUMBER
		FROM () settlement_group

		ORDER BY settlement_group.APPLIED_AT DESC, settlement_group.SETTLEMENT_CODE DESC
	) settlement_page
	WHERE ROWNUM <= #{endRow}
)
WHERE RN >= #{startRow}
